        options: () => [
          { value: 'first', label: 'First person' },
          { value: 'third', label: 'Third person — behind you' },
          { value: 'second', label: 'Second person — in front, looking back' },
        ],
        help: 'Cycles with the perspective key, listed under Controls.',
